//! Builtin module injection.
//!
//! `modules` is generated by `xtask`; this module is the composition root
//! that turns the generated entry calls into a registry.

mod modules;

use depot::Depot;
use extension::builtin::Registry;

/// Builds the registry of every builtin module compiled into this binary.
pub(crate) fn registry() -> Registry<Depot> {
  let mut registry = Registry::new();
  modules::register_all(&mut registry);
  registry
}
